commit 465c5913dce71cde1456e2f0919c97738b8a4636
Author: Sam Fakhreddine <sambou@gmail.com>
Date:   Wed Jul 1 20:28:00 2026 -0600

    fix(record-audio): replace fixed debounce sleeps with condition polling (#198 remainder)

    AudioSessionDetectorTests and AudioSessionDetectorCoreAudioTests slept a
    guessed fixed duration to let the start debounce fire before deactivating,
    which is either too short (flaky under parallel-suite load) or too long
    (slow for no reason). Add a ContinuousClock-based waitForEvent(timeout:_:)
    poll helper, mirroring the isArmed poll pattern used for
    CalendarAwareMeetingDetector, and use it to wait on detector.isActive()
    directly instead of sleeping a magic number.

 .../Unit/AudioSessionDetectorCoreAudioTests.swift  |  2 +-
 .../Tests/Unit/AudioSessionDetectorTests.swift     |  2 +-
 Record-Audio/Tests/Unit/WaitForEvent.swift         | 31 ++++++++++++++++++++++
 3 files changed, 33 insertions(+), 2 deletions(-)
=== helper file ===
import Foundation

/// Thrown by `waitForEvent` when `condition` never becomes true within the deadline.
struct WaitForEventTimeoutError: Error {}

/// Polls `condition` at `pollInterval` until it returns `true`, or throws
/// `WaitForEventTimeoutError` once `timeout` elapses — whichever comes first.
///
/// Replaces fixed `Task.sleep(for:)` calls that guess how long a debounce
/// window or async state transition takes to settle. A guessed sleep is
/// either too short (flaky under load — see #198) or too long (slow for no
/// reason). Polling the actual condition against a `ContinuousClock`
/// deadline fixes both: it returns as soon as the condition is true, and
/// still fails deterministically if it never is.
///
/// Mirrors the `isArmed` poll-loop pattern used for
/// `CalendarAwareMeetingDetector` (Record-ML, #198 Phase 0).
func waitForEvent(
    timeout: Duration = .seconds(2),
    pollInterval: Duration = .milliseconds(10),
    _ condition: @Sendable () async -> Bool
) async throws {
    let clock = ContinuousClock()
    let deadline = clock.now.advanced(by: timeout)
    while await !condition() {
        if clock.now >= deadline {
            throw WaitForEventTimeoutError()
        }
        try await Task.sleep(for: pollInterval)
    }
}

