+    @Test("underlying detached work is cancelled shortly after diarize() times out")
+    func timeoutCancelsOrphanedDetachedTask() async throws {
+        let observer = CancellationObserver()
+        let plugin = FluidDiarizationPlugin(
+            inferenceTimeout: .milliseconds(50),
+            testInference: { _, _ in
+                do {
+                    try await Task.sleep(for: .seconds(5))
+                    return []
+                } catch is CancellationError {
+                    await observer.markCancelled()
+                    throw CancellationError()
+                }
+            }
+        )
+
+        do {
+            _ = try await plugin.diarize(samples: [0.1, 0.2, 0.3], sampleRate: 16000)
+            Issue.record("Expected inferenceFailed timeout error but no error thrown")
+        } catch TranscriptionError.inferenceFailed {
+            // expected — diarize() reports the timeout to its caller.
+        } catch {
+            Issue.record("Unexpected error type: \(error)")
+        }
+
+        // Grace period for the detached task to observe cancellation and report back.
+        // If it's orphaned, this elapses without the flag ever flipping.
+        try await Task.sleep(for: .milliseconds(500))
