 }
+
+/// Observable side effect for `timeoutCancelsOrphanedDetachedTask`: flips to `true`
+/// only if the injected test-inference closure actually observes cancellation.
+private actor CancellationObserver {
+    private(set) var wasCancelled = false
+
+    func markCancelled() {
+        wasCancelled = true
+    }
+}

