import AudioToolbox
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation
import CoreAudio
import Domain
import Foundation
import Logging

// MARK: - Buffer Helpers

extension CoreAudioTapCaptureActor {
    nonisolated static func extractFloats(
        from bufferList: UnsafePointer<AudioBufferList>,
        channelCount: Int
    ) -> [Float] {
        guard channelCount > 0 else { return [] }

        let numberBuffers = Int(bufferList.pointee.mNumberBuffers)
        guard numberBuffers > 0 else { return [] }

        let firstBuffer = bufferList.pointee.mBuffers

        // Single interleaved buffer — return as-is
        if numberBuffers == 1, Int(firstBuffer.mNumberChannels) == channelCount {
            let count = Int(firstBuffer.mDataByteSize / UInt32(MemoryLayout<Float>.size))
            guard let data = firstBuffer.mData?.assumingMemoryBound(to: Float.self) else { return [] }
            return Array(UnsafeBufferPointer(start: data, count: count))
        }

        // Non-interleaved: interleave channels
        let rawPtr = UnsafeMutableRawPointer(mutating: bufferList)
        let buffersOffset = MemoryLayout<AudioBufferList>.size - MemoryLayout<CoreAudio.AudioBuffer>.stride
        let buffersBase = rawPtr.advanced(by: buffersOffset)
            .assumingMemoryBound(to: CoreAudio.AudioBuffer.self)

        let frameCount = Int(firstBuffer.mDataByteSize) / MemoryLayout<Float>.size
        var result: [Float] = []
        result.reserveCapacity(frameCount * channelCount)

        for frame in 0 ..< frameCount {
            for ch in 0 ..< channelCount {
                let bufferPtr = buffersBase.advanced(by: ch)
                guard let data = bufferPtr.pointee.mData else { continue }
                result.append(data.assumingMemoryBound(to: Float.self)[frame])
            }
        }

        return result
    }
}

// MARK: - Aggregate Device + Engine Setup

extension CoreAudioTapCaptureActor {
    /// Creates the tap-only aggregate device, wires it to AVAudioEngine, installs
    /// the resampling tap, and starts the engine.
    ///
    /// Extracted from `start()` to keep that method under the 300-line limit while
    /// retaining a single coherent setup responsibility. All error paths call
    /// `cleanup()` so actor state is never partially initialised on failure.
    // swiftlint:disable:next function_body_length
    func setupAggregateAndEngine(
        sessionID: RecordingID,
        tapUUID: UUID,
        configuration: AudioConfiguration,
        continuation: AsyncStream<DomainAudioBuffer>.Continuation,
        writer: WAVWriter
    ) async throws {
        // Pattern A: Tap-only aggregate (simpler, recommended)
        let aggDesc: [String: Any] = [
            kAudioAggregateDeviceNameKey as String: "TheRecordTap",
            kAudioAggregateDeviceUIDKey as String: "app.the-record.tap.\(sessionID.rawValue)",
            kAudioAggregateDeviceIsPrivateKey as String: true,
            kAudioAggregateDeviceTapAutoStartKey as String: true,
            kAudioAggregateDeviceTapListKey as String: [
                [
                    kAudioSubTapUIDKey as String: tapUUID.uuidString,
                    kAudioSubTapDriftCompensationKey as String: NSNumber(value: 1),
                ],
            ],
        ]

        var aggDeviceID: AudioObjectID = .init(kAudioObjectUnknown)
        let aggStatus = AudioHardwareCreateAggregateDevice(aggDesc as CFDictionary, &aggDeviceID)
        guard aggStatus == noErr else {
            // T015: reset tapID before cleanup() so cleanup()'s destroy guard is a no-op,
            // preventing double-destroy of the tap (undefined behaviour / potential crash).
            AudioHardwareDestroyProcessTap(resources.tapID)
            resources.tapID = .init(kAudioObjectUnknown)
            logger.error("AudioHardwareCreateAggregateDevice failed: \(aggStatus, privacy: .private)")
            if aggStatus == kAudioHardwareNotRunningError || aggStatus == 0x2161_7574 || aggStatus < 0 {
                throw AudioError.permissionDenied(
                    // swiftlint:disable:next line_length
                    message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                )
            }
            throw AudioError.captureFailed(underlying: NSError(
                domain: NSOSStatusErrorDomain, code: Int(aggStatus)
            ))
        }
        resources.aggregateDeviceID = aggDeviceID

        // Poll until the HAL finishes wiring the tap into the aggregate device.
        // kAudioAggregateDevicePropertyFullSubDeviceList is empty until ready;
        // 100ms blind sleep was unreliable under load (finding #22).
        try await waitForAggregateDeviceReady(id: aggDeviceID)

        // Set up AVAudioEngine with aggregate device as input
        let newEngine = AVAudioEngine()
        engine = newEngine

        // Set aggregate device as the input device
        guard let inputNode = newEngine.inputNode.audioUnit else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }
        var devID = aggDeviceID
        let setStatus = AudioUnitSetProperty(
            inputNode,
            kAudioOutputUnitProperty_CurrentDevice,
            kAudioUnitScope_Global, 0,
            &devID,
            UInt32(MemoryLayout<AudioObjectID>.size)
        )
        guard setStatus == noErr else {
            let setFourCC = String(
                bytes: withUnsafeBytes(of: setStatus.bigEndian) { Array($0) },
                encoding: .ascii
            ) ?? "????"
            cleanup()
            logger.error(
                "AudioUnitSetProperty(CurrentDevice) failed: \(setStatus) ('\(setFourCC, privacy: .private)')"
            )
            if setStatus == kAudioHardwareNotRunningError || setStatus == 0x2161_7574 || setStatus < 0 {
                throw AudioError.permissionDenied(
                    message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                )
            }
            throw AudioError.captureFailed(underlying: NSError(
                domain: NSOSStatusErrorDomain, code: Int(setStatus)
            ))
        }

        let inputFormat = newEngine.inputNode.inputFormat(forBus: 0)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Tap input format: \(inputFormat.sampleRate, privacy: .private) Hz, \(inputFormat.channelCount, privacy: .public) ch"
            )

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: configuration.sampleRate,
            channels: AVAudioChannelCount(configuration.channels),
            interleaved: false
        ) else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }
        guard let converter = AVAudioConverter(from: inputFormat, to: targetFormat) else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }

        // Prefer the shared tick from configuration so both audio streams share the same epoch.
        let tapT0: UInt64 = configuration.sessionStartTick != 0
            ? configuration.sessionStartTick
            : mach_absolute_time()
        self.tapT0 = tapT0

        installConverterTap(
            inputFormat: inputFormat,
            targetFormat: targetFormat,
            converter: converter,
            tapT0: tapT0,
            continuation: continuation,
            writer: writer,
            configuration: configuration
        )

        try newEngine.start()

        // #244: observe hardware reconfiguration so a mid-session sample-rate
        // change (e.g. output device switch) rebuilds the converter instead of
        // silently mis-converting with the stale ratio (root cause of
        // time-stretched WAVs / broken diarization timestamps).
        registerRouteChangeObserver(engine: newEngine)
    }
}

// MARK: - Error Handling

final class ConverterErrorTracker: @unchecked Sendable {
    var consecutiveFailures = 0
    let failureThreshold: Int
    let onFailure: (String) -> Void

    init(failureThreshold: Int, onFailure: @escaping (String) -> Void) {
        self.failureThreshold = failureThreshold
        self.onFailure = onFailure
    }

    func recordFailure(_ error: NSError) -> Bool {
        consecutiveFailures += 1
        onFailure(
            "AVAudioConverter error (consecutive count: \(consecutiveFailures)): \(error.localizedDescription)"
        )

        if consecutiveFailures >= failureThreshold {
            onFailure("Converter failures reached threshold (\(failureThreshold)), terminating stream")
            consecutiveFailures = 0
            return true
        }
        return false
    }

    func recordSuccess() {
        consecutiveFailures = 0
    }
}


// MARK: - Private Helpers

extension CoreAudioTapCaptureActor {
    // NOTE: defaultOutputDeviceUID() cannot be made `private` here because it is called
    // from CoreAudioTapCaptureActor.swift via Self.defaultOutputDeviceUID(). Cross-file
    // extensions in Swift cannot access private members of the primary declaration file.
    // TODO(5.8): Resolve via module-level access control when Infrastructure becomes its own SwiftPM target.
    static func defaultOutputDeviceUID() throws -> String {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var deviceID = AudioDeviceID(kAudioObjectUnknown)
        var dataSize = UInt32(MemoryLayout<AudioDeviceID>.size)
        var err = AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject),
            &address, 0, nil, &dataSize, &deviceID
        )
        guard err == noErr, deviceID != AudioDeviceID(kAudioObjectUnknown) else {
            throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(err)))
        }

        address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyDeviceUID,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var uid: CFString = "" as CFString
        dataSize = UInt32(MemoryLayout<CFString>.size)
        err = withUnsafeMutablePointer(to: &uid) { ptr in
            AudioObjectGetPropertyData(deviceID, &address, 0, nil, &dataSize, ptr)
        }
        guard err == noErr else {
            throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(err)))
        }
        return uid as String
    }

    nonisolated func makeFileURL(for date: Date) -> URL {
        let cal = Calendar.current
        let y = String(cal.component(.year, from: date))
        let m = String(format: "%02d", cal.component(.month, from: date))
        let name = date.formatted(.iso8601) + ".wav"
        return recordingDirectory.appendingPathComponent(y).appendingPathComponent(m)
            .appendingPathComponent(name)
    }
}

// NOTE: internal (not private) so CoreAudioTapCaptureActorRouteChange.swift's
// installConverterTap(...) can construct it during a tap rebuild (#244).
final class TapConverterInputFlag: @unchecked Sendable { var value = false }

import Domain
import Foundation
import Logging
import os
import Utilities

/// Crash-isolated MLX summarization via an external MCP subprocess.
///
/// Keeps the model warm in a separate process. If the subprocess crashes,
/// the main app survives and reports the failure gracefully.
public actor MCPSummarizationPlugin: SummarizationEngine {
    private let launchPath: String
    private let fixedArguments: [String]
    private let logger = AppLogger.for(category: "MCPSummarization")
    private var process: Process?
    private var stdinPipe: Pipe?
    private var stdoutPipe: Pipe?
    private var isModelReady = false

    public init(launchPath: String, arguments: [String] = []) {
        self.launchPath = launchPath
        fixedArguments = arguments
    }

    deinit {
        stdinPipe?.fileHandleForWriting.closeFile()
        stdinPipe?.fileHandleForReading.closeFile()
        stdoutPipe?.fileHandleForWriting.closeFile()
        stdoutPipe?.fileHandleForReading.closeFile()
        process?.terminate()
    }

    /// The OS process identifier of the running MCP subprocess, or nil if not loaded.
    /// Exposed for test verification of process lifecycle (kill/ESRCH checks).
    var processIdentifier: Int32? {
        process?.processIdentifier
    }

    public func loadModel(_ config: SummaryConfig) async throws {
        if isModelReady, let p = process, p.isRunning { return }

        let proc = Process()
        proc.executableURL = URL(fileURLWithPath: launchPath)
        proc.arguments = fixedArguments.isEmpty ? [config.modelId.rawValue] : fixedArguments
        let newStdin = Pipe()
        let newStdout = Pipe()
        proc.standardInput = newStdin
        proc.standardOutput = newStdout
        proc.standardError = FileHandle.nullDevice

        do {
            try proc.run()
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Failed to launch MCP subprocess: \(errDesc, privacy: .public)")
            throw SummarizationError.modelNotLoaded(underlying: error)
        }

        // Give subprocess a moment to initialize
        try await Task.sleep(for: .milliseconds(50))

        guard proc.isRunning else {
            throw SummarizationError.modelNotLoaded(underlying: nil)
        }

        stdinPipe = newStdin
        stdoutPipe = newStdout
        process = proc
        isModelReady = true
        logger.info("MCP subprocess launched at PID \(proc.processIdentifier, privacy: .private)")
    }

    /// Terminates the MCP subprocess and resets ready state. Safe to call
    /// when no process is running. Wire to app-lifecycle teardown (#29).
    public func shutdown() {
        stdinPipe?.fileHandleForWriting.closeFile()
        stdinPipe?.fileHandleForReading.closeFile()
        stdoutPipe?.fileHandleForWriting.closeFile()
        stdoutPipe?.fileHandleForReading.closeFile()
        if let p = process, p.isRunning {
            p.terminate()
            p.waitUntilExit()
        }
        process = nil
        stdinPipe = nil
        stdoutPipe = nil
        isModelReady = false
        logger.info("MCP subprocess shut down")
    }

    // MARK: - MCP Request Types

    private struct MCPRequest: Encodable {
        let jsonrpc = "2.0"
        let id = 1
        let method = "tools/call"
        let params: Params

        struct Params: Encodable {
            let name = "summarize"
            let arguments: Arguments
        }

        struct Arguments: Encodable {
            let transcript: String
            let speakers: [String]
        }
    }

    public func summarize(
        transcript: String, speakers: [String], meetingType _: MeetingType
    ) async throws -> MeetingSummary {
        guard let proc = process, proc.isRunning else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        guard let stdin = stdinPipe,
              let stdout = stdoutPipe
        else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        let request = MCPRequest(params: .init(arguments: .init(transcript: transcript, speakers: speakers)))
        let requestData = try JSONEncoder().encode(request)
        let header = "Content-Length: \(requestData.count)\r\n\r\n"
        guard let headerData = header.data(using: .utf8) else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        // Write on a detached task to avoid blocking the actor executor
        let stdinHandle = stdin.fileHandleForWriting
        await Task.detached {
            stdinHandle.write(headerData)
            stdinHandle.write(requestData)
        }.value

        // Read response with timeout — DispatchQueue bridges the blocking pipe read off the
        // cooperative thread pool. Task.detached is insufficient: it still parks a cooperative
        // thread on the synchronous availableData call and cannot be interrupted by cancellation.
        let stdoutHandle = stdout.fileHandleForReading
        let responseData: Data = try await withThrowingTaskGroup(of: Data.self) { group in
            group.addTask {
                let continuationBox = OSAllocatedUnfairLock<CheckedContinuation<Data, Never>?>(initialState: nil)
                return await withTaskCancellationHandler {
                    await withCheckedContinuation { (cont: CheckedContinuation<Data, Never>) in
                        continuationBox.withLock { $0 = cont }
                        DispatchQueue.global(qos: .userInitiated).async {
                            let data = stdoutHandle.availableData
                            let c = continuationBox.withLock { box -> CheckedContinuation<Data, Never>? in
                                let tmp = box
                                box = nil
                                return tmp
                            }
                            c?.resume(returning: data)
                        }
                    }
                } onCancel: {
                    let c = continuationBox.withLock { box -> CheckedContinuation<Data, Never>? in
                        let tmp = box
                        box = nil
                        return tmp
                    }
                    c?.resume(returning: Data())
                }
            }
            group.addTask {
                try await Task.sleep(for: TimeoutConfig.mcpResponse)
                throw SummarizationError.generationFailed(underlying: nil)
            }
            guard let result = try await group.next() else {
                throw SummarizationError.generationFailed(underlying: nil)
            }
            group.cancelAll()
            return result
        }

        guard !responseData.isEmpty else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        // Parse MCP response → MeetingSummary
        let json: [String: Any]
        do {
            guard let parsed = try JSONSerialization.jsonObject(with: responseData) as? [String: Any] else {
                let raw = String(data: responseData, encoding: .utf8) ?? "<binary>"
                logger.error("MCP response type mismatch (expected dict) — raw: \(raw, privacy: .private)")
                throw SummarizationError.generationFailed(underlying: nil)
            }
            json = parsed
        } catch {
            let raw = String(data: responseData, encoding: .utf8) ?? "<binary>"
            logger.error("MCP response JSON parse failed: \(String(reflecting: error), privacy: .public) — raw: \(raw, privacy: .private)")
            throw SummarizationError.generationFailed(underlying: error)
        }

        guard let result = json["result"] as? [String: Any],
              let content = result["content"] as? [[String: Any]],
              let text = content.first?["text"] as? String,
              let summaryData = text.data(using: .utf8)
        else {
            let raw = String(data: responseData, encoding: .utf8) ?? "<binary>"
            logger.error("MCP response structure validation failed — raw: \(raw, privacy: .private)")
            throw SummarizationError.generationFailed(underlying: nil)
        }

        do {
            return try JSONDecoder().decode(MeetingSummary.self, from: summaryData)
        } catch {
            let truncated = String(text.prefix(100))
            logger
                .error(
                    // swiftlint:disable:next line_length
                    "MeetingSummary decode failed: \(String(reflecting: error), privacy: .private) — raw (truncated): \(truncated, privacy: .private)"
                )
            throw SummarizationError.generationFailed(underlying: error)
        }
    }

    public func isReady() async -> Bool {
        guard isModelReady, let p = process else { return false }
        return p.isRunning
    }

    public func generate(prompt: String) async throws -> String {
        throw SummarizationError.generationFailed(underlying: nil)
    }
}

import AudioToolbox
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation
import CoreAudio
import Domain
import Foundation
import Logging

// MARK: - Route-change handling (#244)

/// Fixes the diarization root cause: `CoreAudioTapCaptureActor` used to read
/// the tap's input format once at `setupAggregateAndEngine` time and never
/// revisit it. A mid-session sample-rate change (route/device switch) left the
/// `AVAudioConverter` assuming a stale input rate, silently time-stretching the
/// recorded WAV by 1.6-1.9x and corrupting every downstream transcript/
/// diarization timestamp.
///
/// Mirrors the `MicCaptureActorRouteChange.handleConfigurationChange()` pattern
/// (#49): observe `.AVAudioEngineConfigurationChange`, remove the stale tap,
/// re-read the input format, rebuild the converter, reinstall the tap, restart
/// the engine — reusing the existing continuation/writer/tapT0 so the recording
/// session is uninterrupted.
extension CoreAudioTapCaptureActor {
    /// Registers the config-change observer on `engine`. Removed in `cleanup()`.
    func registerRouteChangeObserver(engine: AVAudioEngine) {
        let observer = NotificationCenter.default.addObserver(
            forName: .AVAudioEngineConfigurationChange,
            object: engine,
            queue: nil
        ) { [weak self] _ in
            Task { await self?.handleTapConfigurationChange() }
        }
        routeChangeObserver = observer
    }

    /// Rebuilds the tap converter after a mid-session hardware reconfiguration.
    ///
    /// Reuses `streamContinuation`, `wavWriter`, and `tapT0` so the in-flight
    /// recording session keeps writing to the same file with a continuous
    /// timestamp epoch — only the input format and converter are rebuilt.
    func handleTapConfigurationChange() async {
        guard state == .recording,
              let eng = engine,
              let writer = wavWriter,
              let continuation = streamContinuation,
              let configuration = sessionConfiguration
        else { return }

        eng.inputNode.removeTap(onBus: 0)

        let newInputFormat = eng.inputNode.inputFormat(forBus: 0)
        guard newInputFormat.sampleRate > 0, newInputFormat.channelCount > 0 else {
            logger.error("Route change: new tap input format invalid — system audio capture cannot resume")
            return
        }

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: configuration.sampleRate,
            channels: AVAudioChannelCount(configuration.channels),
            interleaved: false
        ) else {
            logger.error("Route change: cannot rebuild target format")
            return
        }

        guard let newConverter = AVAudioConverter(from: newInputFormat, to: targetFormat) else {
            logger.error("Route change: cannot rebuild converter from new tap input format")
            return
        }

        installConverterTap(
            inputFormat: newInputFormat,
            targetFormat: targetFormat,
            converter: newConverter,
            tapT0: tapT0,
            continuation: continuation,
            writer: writer,
            configuration: configuration
        )

        do {
            try eng.start()
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "Route change handled — system tap resumed (sampleRate=\(newInputFormat.sampleRate, privacy: .private))"
                )
        } catch {
            logger.error(
                "Route change: failed to restart tap engine — \(String(reflecting: error), privacy: .public)"
            )
        }
    }

    /// Installs the resampling tap on `engine.inputNode`, wiring up conversion,
    /// error tracking, and WAV persistence. Shared by the initial `start()` setup
    /// and `handleTapConfigurationChange()`'s rebuild so both paths stay in sync.
    ///
    /// Defensive second layer (#244): inside the callback, the buffer's own
    /// `format.sampleRate` is authoritative. If it disagrees with `inputFormat`
    /// (the rate the converter was built for) a rebuild is triggered — this
    /// catches the race where a buffer arrives before the observer-driven
    /// rebuild above has completed.
    func installConverterTap(
        inputFormat: AVAudioFormat,
        targetFormat: AVAudioFormat,
        converter: AVAudioConverter,
        tapT0: UInt64,
        continuation: AsyncStream<DomainAudioBuffer>.Continuation,
        writer: WAVWriter,
        configuration: AudioConfiguration
    ) {
        guard let newEngine = engine else { return }

        let errorTracker = ConverterErrorTracker(
            failureThreshold: converterFailureThreshold,
            onFailure: { [weak self] msg in
                self?.logger.error("\(msg, privacy: .private)")
            }
        )

        newEngine.inputNode
            .installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] inBuffer, when in
                guard let self else { return }

                if inBuffer.format.sampleRate != inputFormat.sampleRate {
                    self.logger.error(
                        // swiftlint:disable:next line_length
                        "Tap buffer sampleRate \(inBuffer.format.sampleRate, privacy: .private) != expected \(inputFormat.sampleRate, privacy: .private) — triggering rebuild"
                    )
                    Task { await self.handleTapConfigurationChange() }
                    return
                }

                let ratio = configuration.sampleRate / inputFormat.sampleRate
                let outFrameCount = AVAudioFrameCount(Double(inBuffer.frameLength) * ratio)
                guard let outBuffer = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: outFrameCount)
                else { return }

                let consumed = TapConverterInputFlag()
                var error: NSError?
                converter.convert(to: outBuffer, error: &error) { _, status in
                    guard !consumed.value else {
                        status.pointee = .noDataNow
                        return nil
                    }
                    consumed.value = true
                    status.pointee = .haveData
                    return inBuffer
                }

                if let error {
                    if errorTracker.recordFailure(error) {
                        continuation.finish()
                    }
                    return
                }

                guard let channelData = outBuffer.floatChannelData?[0] else { return }
                let floatArray = Array(UnsafeBufferPointer(start: channelData, count: Int(outBuffer.frameLength)))
                guard !floatArray.isEmpty else { return }

                // Reset consecutive failure counter on successful conversion
                errorTracker.recordSuccess()

                let ts = MachClock.ticksToSeconds(when.hostTime &- tapT0)
                let domainBuffer = DomainAudioBuffer(
                    sampleRate: configuration.sampleRate,
                    channelCount: configuration.channels,
                    samples: floatArray,
                    timestamp: ts
                )
                if case .dropped = continuation.yield(domainBuffer) {
                    self.logger.warning("System audio buffer dropped — stream full, frames lost")
                }
                writer.append(floatArray)
            }
    }
}

